namespace neurozen.API.IAM.Application.Internal.Configuration;

/// <summary>
///     Versions of the legal documents currently published by the frontend ("Legal" section, optional).
///     They are recorded with each consent. The values are identifiers only: the legal texts are owned by the
///     project / legal team and are not generated by the backend. Update them whenever a document changes.
/// </summary>
public class LegalSettings
{
    public string TermsVersion { get; set; } = "1.0";
    public string PrivacyPolicyVersion { get; set; } = "1.0";
}
